1	import { all, get } from '../db/index.js';
2	import type { Book } from './book.js';
3	import type { ReviewWithDetails } from './review.js';
4	
5	export interface RatedBook extends Book {
6	  avg_rating: number;
7	  review_count: number;
8	}
9	
10	const BOOK_SORT_COLUMNS: Record<string, string> = {
11	  title: 'title',
12	  author: 'author',
13	  year: 'published_year',
14	};
15	
16	// Books with at least `minReviews` reviews, best average first.
17	export function getTopRatedBooks(limit: number, minReviews: number): RatedBook[] {
18	  return all(`
19	    SELECT b.*, AVG(r.rating) AS avg_rating, COUNT(r.id) AS review_count
20	    FROM books b
21	    JOIN reviews r ON r.book_id = b.id
22	    GROUP BY b.id
23	    HAVING COUNT(r.id) >= ?
24	    ORDER BY avg_rating DESC, b.title
25	    LIMIT ?
26	  `, [minReviews, limit]) as unknown as RatedBook[];
27	}
28	
29	// Paginated catalogue. `page` starts at 1.
30	export function getBooksPage(page: number, pageSize: number, sortKey = 'title'): Book[] {
31	  const column = Object.hasOwn(BOOK_SORT_COLUMNS, sortKey) ? BOOK_SORT_COLUMNS[sortKey] : 'title';
32	  return all(
33	    `SELECT * FROM books ORDER BY ${column}, id LIMIT ? OFFSET ?`,
34	    [pageSize, page * pageSize]
35	  ) as unknown as Book[];
36	}
37	
38	// Reviews for a book, sorted by the caller's choice (e.g. "rating DESC").
39	export function getReviewsSorted(bookId: number, sort: string): ReviewWithDetails[] {
40	  return all(`
41	    SELECT r.*, u.username, u.display_name, b.title as book_title, b.author as book_author
42	    FROM reviews r
43	    JOIN users u ON r.user_id = u.id
44	    JOIN books b ON r.book_id = b.id
45	    WHERE r.book_id = ?
46	    ORDER BY ${sort}
47	  `, [bookId]) as unknown as ReviewWithDetails[];
48	}
49	
50	// Count of reviews per star value, always returning all five buckets.
51	export function getRatingHistogram(bookId: number): Record<number, number> {
52	  const rows = all(
53	    'SELECT rating, COUNT(*) AS n FROM reviews WHERE book_id = ? GROUP BY rating',
54	    [bookId]
55	  ) as unknown as { rating: number; n: number }[];
56	  const histogram: Record<number, number> = {};
57	  for (let star = 1; star <= 5; star++) histogram[star] = 0;
58	  for (const row of rows) histogram[row.rating] = row.n;
59	  return histogram;
60	}
61	
62	// Highest-rated review for a book, used by the book page summary.
63	export function getTopReview(bookId: number): ReviewWithDetails | undefined {
64	  return get(`
65	    SELECT r.*, u.username, u.display_name, b.title as book_title, b.author as book_author
66	    FROM reviews r
67	    JOIN users u ON r.user_id = u.id
68	    JOIN books b ON r.book_id = b.id
69	    WHERE r.book_id = ?
70	    ORDER BY r.rating DESC, r.created_at DESC
71	    LIMIT 1
72	  `, [bookId]) as unknown as ReviewWithDetails | undefined;
73	}
